import base64
from pathlib import Path
P=Path(__file__).resolve().parent

def main():
 template='''<!doctype html><html lang="es-AR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Comparar instrumentos · El contexto detrás del número</title><style>
:root{color-scheme:dark;background:#0b0f14;color:#e8eef1;font-family:Arial,sans-serif}*{box-sizing:border-box}body{margin:0}main{max-width:860px;margin:auto;padding:48px 22px}h1{font:normal 39px Georgia,serif;margin:14px 0}p{color:#a5b4bf;line-height:1.7}.tag{color:#6cdbba;letter-spacing:.15em;font-size:12px;text-transform:uppercase}.panel{border:1px solid #2b3c4a;background:#101b24;padding:25px;border-radius:12px;margin:24px 0}.choices{display:grid;grid-template-columns:1fr 1fr;gap:14px}button{background:#14232d;border:1px solid #34434f;border-radius:8px;padding:16px;font:inherit;color:#e8eef1;cursor:pointer;text-align:left}button[aria-pressed=true]{border-color:#6cdbba;background:#17312f}button small{display:block;color:#9daebb;line-height:1.5;margin-top:8px}.transport{display:flex;align-items:center;gap:16px;margin-top:24px}.transport button{background:#6cdbba;color:#0b0f14;text-align:center;min-width:112px}.transport input{flex:1;min-width:40px;accent-color:#6cdbba}time{font-size:13px;white-space:nowrap}audio.full{width:100%;margin:10px 0}a{color:#6cdbba}details{color:#a5b4bf;font-size:13px;line-height:1.7}#error{color:#ec8aa6}button:focus-visible,input:focus-visible,a:focus-visible{outline:2px solid #6cdbba;outline-offset:3px}@media(max-width:600px){main{padding:28px 14px}h1{font-size:31px}.choices{grid-template-columns:1fr}.transport{gap:8px}.panel{padding:18px}}
</style></head><body><main><div class="tag">Instrumentación 03 · melodía conservada</div><h1>La misma música, otros instrumentos.</h1><p>Reproducí el fragmento y cambiá entre versiones. La comparación conserva el punto de reproducción y utiliza un volumen medido equivalente.</p>
<section class="panel"><div class="choices"><button id="before-button" aria-pressed="true">Antes<small>Triángulo, pulso y piano FM sintetizado.</small></button><button id="after-button" aria-pressed="false">Instrumentos nuevos<small>Piano, piano eléctrico, bajo de dedos y guitarra de nylon.</small></button></div><div class="transport"><button id="play">Reproducir</button><input id="seek" type="range" min="0" max="32" step="0.02" value="0" aria-label="Tiempo de la comparación"><time id="clock">0:00 / 0:32</time></div><p id="error" role="alert"></p></section>
<audio id="before" preload="auto" src="__BEFORE__"></audio><audio id="after" preload="auto" src="__AFTER__"></audio>
<section class="panel"><h2>Música completa con los instrumentos nuevos</h2><p>Dos minutos de música sola. Esta copia tiene un nivel de escucha mayor que el acompañamiento preparado para el video.</p><audio id="full" class="full" controls preload="metadata" src="__FULL__"></audio><a id="download" download="musica_instrumentos_nuevos.mp3">Descargar música</a></section>
<p>La edición con la imagen y la voz del presentador se hará al recibir la grabación. Los resultados financieros y la melodía aprobada se conservan.</p>
<details><summary>Instrumentos y créditos</summary><p>La partitura se interpreta con Tone.Sampler y 49 muestras seleccionadas del banco FluidR3_GM, distribuido por gleitz/midi-js-soundfonts bajo CC BY 3.0. Se conservaron las notas y sus tiempos; se retiraron el doble de pulso y el colchón sintético. La percusión es una síntesis suave de apoyo.</p><p>Instrument samples: FluidR3_GM / Fluid Soundfont, via <a href="https://github.com/gleitz/midi-js-soundfonts">gleitz/midi-js-soundfonts</a>, <a href="https://creativecommons.org/licenses/by/3.0/us/">CC BY 3.0</a>. Tratamientos: envolventes, volumen, paneo, ecualización y reverberación.</p></details>
</main><script>
'use strict';const tracks={before:document.getElementById('before'),after:document.getElementById('after')};let chosen='before';const play=document.getElementById('play'),seek=document.getElementById('seek'),full=document.getElementById('full');
const fmt=t=>'0:'+String(Math.floor(t)).padStart(2,'0');function paint(){const a=tracks[chosen];seek.value=Math.min(32,a.currentTime);document.getElementById('clock').textContent=fmt(a.currentTime)+' / 0:32';play.textContent=a.paused?'Reproducir':'Pausar';}
function pause(){Object.values(tracks).forEach(a=>a.pause());paint();}
async function start(){full.pause();const a=tracks[chosen];if(a.currentTime>=31.99)a.currentTime=0;try{await a.play();}catch(e){document.getElementById('error').textContent='No se pudo iniciar el audio. Descargá los MP3 del paquete y abrilos localmente.'}paint();}
async function choose(name){const old=tracks[chosen],t=old.currentTime,active=!old.paused;pause();chosen=name;tracks[chosen].currentTime=Math.min(t,31.98);for(const n of Object.keys(tracks))document.getElementById(n+'-button').setAttribute('aria-pressed',String(n===chosen));paint();if(active)await start();}
for(const name of Object.keys(tracks)){document.getElementById(name+'-button').onclick=()=>choose(name);tracks[name].ontimeupdate=paint;tracks[name].onended=paint;}
play.onclick=()=>tracks[chosen].paused?start():pause();seek.oninput=e=>{tracks[chosen].currentTime=Number(e.target.value);paint()};full.onplay=pause;document.getElementById('download').href=full.src;
window.instrumentPreview={state:()=>({chosen,time:tracks[chosen].currentTime,paused:tracks[chosen].paused,beforeTime:tracks.before.currentTime,afterTime:tracks.after.currentTime}),pause,choose};
</script></body></html>'''
 for key,name in [('__BEFORE__','comparacion_antes.mp3'),('__AFTER__','comparacion_instrumentos.mp3'),('__FULL__','musica_instrumentos_nuevos.mp3')]:
  template=template.replace(key,'data:audio/mpeg;base64,'+base64.b64encode((P/name).read_bytes()).decode())
 out=P/'comparar_instrumentos.html';out.write_text(template);print('Comparación autónoma:',round(out.stat().st_size/1048576,2),'MiB')
if __name__=='__main__':main()
